            log_message(LOG_LEVEL_ALWAYS, "unknown return from scp_vXs_accept()");
            break;
    }

    free_stream(scon.in_s);
    free_stream(scon.out_s);

    if (sdata)
    {
        scp_session_destroy(sdata);
    }

    return 0;
}

