/// This represents a JavaScript variable, that's allocated in the function.
class Variable : public Value {
 public:
  enum class DeclKind {
    Var,
    Let,
    Const,
  };

  /// Return true if this DeclKind needs to track TDZ.
  static bool declKindNeedsTDZ(DeclKind dk) {
    return dk != DeclKind::Var;
  }

 private:
  Variable(const Variable &) = delete;
  void operator=(const Variable &) = delete;

  /// Declaration kind: var/let/const.
  DeclKind declKind;

  /// The textual representation of the variable in the JavaScript program.
  Identifier text;

  /// The scope that owns the variable.
  VariableScope *parent;

  /// In a "let" or "const" variable this points to the validity flag.
  /// In a "var" variable, if relatedVariable_ is non-null, then the variable is
  /// itself the validity flag and relatedVariable_ points to the let/const.
  Variable *relatedVariable_{};

 protected:
  explicit Variable(
      ValueKind k,
      VariableScope *scope,
      DeclKind declKind,
      Identifier txt);

 public:
  explicit Variable(VariableScope *scope, DeclKind declKind, Identifier txt)
      : Variable(ValueKind::VariableKind, scope, declKind, txt){};

  ~Variable();

  DeclKind getDeclKind() const {
    return declKind;
  }

  Identifier getName() const {
    return text;
  }
  VariableScope *getParent() const {
    return parent;
  }

  Variable *getRelatedVariable() const {
    return relatedVariable_;
  }
  void setRelatedVariable(Variable *relatedVariable) {
    assert(
        (!relatedVariable || !relatedVariable->relatedVariable_ ||
         relatedVariable->relatedVariable_ == this) &&
        "Related variable should be null or point back to us");
    relatedVariable_ = relatedVariable;
  }

  /// Return the index of this variable in the function's variable list.
  int getIndexInVariableList() const;

  static bool classof(const Value *V) {
    return V->getKind() == ValueKind::VariableKind;
  }
};

