  explicit Variable(
      ValueKind k,
      VariableScope *scope,
      DeclKind declKind,
      Identifier txt);

 public:
  explicit Variable(VariableScope *scope, DeclKind declKind, Identifier txt)
      : Variable(ValueKind::VariableKind, scope, declKind, txt){};

