  E(bool,           EmitInstMethPointers,             false)          \
  H(bool,           AllowUnstableFeatures,            false)          \
  H(bool,           DisallowHashComments,             false)          \
  H(bool,           EnableXHPClassModifier,           true)           \
  H(bool,           DisableXHPElementMangling,        true)           \
